// AuthContext.tsx
import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, AuthContextType, RegisterData } from '../types/auth';
import { authService } from '../services/authService';

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(localStorage.getItem('token'));
  const [isLoading, setIsLoading] = useState(true);
  const [userMinioInfo, setUserMinioInfo] = useState<any>(null);

  useEffect(() => {
    const initAuth = async () => {
      const savedToken = localStorage.getItem('token');
      if (savedToken) {
        if (authService.isTokenExpired(savedToken)) {
          console.log('❌ Token expired, clearing storage');
          localStorage.removeItem('token');
          localStorage.removeItem('user');
          setToken(null);
          setUser(null);
        } else {
          try {
            console.log('🔄 Initializing auth from stored token...');
            const userData = await authService.getCurrentUser(savedToken);
            setUser(userData);
            
            // Получаем MinIO информацию
            try {
              const minioInfo = await authService.getUserMinioInfo(savedToken);
              setUserMinioInfo(minioInfo);
            } catch (minioError) {
              console.warn('⚠️ Could not fetch MinIO info:', minioError);
            }
            
            console.log('✅ User authenticated:', userData.username);
          } catch (error) {
            console.error('❌ Failed to get user data:', error);
            handleLogout();
          }
        }
      }
      setIsLoading(false);
    };

    initAuth();
  }, []);

  const login = async (username: string, password: string): Promise<User> => {
    setIsLoading(true);
    try {
      console.log(`🔄 Login attempt for: ${username}`);
      
      const authResponse = await authService.login(username, password);
      const { access_token } = authResponse;
      
      console.log('✅ Token received, storing...');
      
      setToken(access_token);
      localStorage.setItem('token', access_token);
      
      console.log('🔄 Getting user data...');
      const userData = await authService.getCurrentUser(access_token);
      setUser(userData);
      localStorage.setItem('user', JSON.stringify(userData));
      
      // Получаем MinIO информацию
      try {
        const minioInfo = await authService.getUserMinioInfo(access_token);
        setUserMinioInfo(minioInfo);
      } catch (minioError) {
        console.warn('⚠️ Could not fetch MinIO info:', minioError);
      }
      
      console.log('🎉 Login successful:', userData.username);
      return userData;
    } catch (error) {
      console.error('❌ Login failed:', error);
      handleLogout();
      throw error;
    } finally {
      setIsLoading(false);
    }
  };

  const register = async (data: RegisterData): Promise<User> => {
    setIsLoading(true);
    try {
      console.log(`🔄 Registration attempt for: ${data.username}`);
      
      const userData = await authService.register(data);
      
      // После регистрации автоматически логиним пользователя
      console.log('🔄 Auto-login after registration...');
      await login(data.username, data.password);
      
      console.log('🎉 Registration and login successful');
      return userData;
    } catch (error) {
      console.error('❌ Registration failed:', error);
      throw error;
    } finally {
      setIsLoading(false);
    }
  };

  const updateUser = async (updatedUser: Partial<User>): Promise<void> => {
    try {
      console.log('🔄 Updating user data...');
      // Здесь можно добавить вызов API для обновления данных пользователя
      setUser(prev => prev ? { ...prev, ...updatedUser } : null);
    } catch (error) {
      console.error('❌ Failed to update user:', error);
      throw error;
    }
  };

  const handleLogout = () => {
    console.log('👋 Logging out...');
    setUser(null);
    setToken(null);
    setUserMinioInfo(null);
    localStorage.removeItem('token');
    localStorage.removeItem('user');
  };

  const logout = () => {
    handleLogout();
    console.log('✅ User logged out');
  };

  const value: AuthContextType = {
    user,
    token,
    login,
    logout,
    isLoading,
    register,
    updateUser,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
